$ErrorActionPreference='Stop'
$Port=47821
$Root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))
$RecordDir=Join-Path $Root 'Recordings'
$ConfigDir=Join-Path $Root 'Config'
$ConfigFile=Join-Path $ConfigDir 'settings.json'
$Scrcpy=Join-Path $Root 'core\scrcpy\scrcpy.exe'
$Adb=Join-Path $Root 'core\scrcpy\adb.exe'
$Listener=New-Object Net.HttpListener
$Listener.Prefixes.Add("http://127.0.0.1:$Port/")
New-Item -ItemType Directory -Force -Path $RecordDir,$ConfigDir | Out-Null
$Default=@{maxSize=1280;maxFps=30;bitrate='8M';audio=$true}
if(-not(Test-Path $ConfigFile)){$Default|ConvertTo-Json|Set-Content -Encoding UTF8 $ConfigFile}
function Settings {try{$s=Get-Content -Raw $ConfigFile|ConvertFrom-Json;if(@(720,1024,1280,1600,1920,0)-notcontains[int]$s.maxSize){throw 'size'};if(@(15,24,30,45,60)-notcontains[int]$s.maxFps){throw 'fps'};if(@('2M','4M','8M','12M','16M')-notcontains[string]$s.bitrate){throw 'bitrate'};return @{maxSize=[int]$s.maxSize;maxFps=[int]$s.maxFps;bitrate=[string]$s.bitrate;audio=[bool]$s.audio}}catch{return $Default}}
function Reply($c,$data,$status=200){$b=[Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $data -Depth 8 -Compress));$c.Response.StatusCode=$status;$c.Response.ContentType='application/json; charset=utf-8';$c.Response.Headers['Access-Control-Allow-Origin']='*';$c.Response.Headers['Cache-Control']='no-store';$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}
function Devices {if(-not(Test-Path $Adb)){return @{devices=@();message='adb.exe is missing from the toolkit root.'}};$lines=@(& $Adb devices -l 2>&1);$items=@();foreach($line in $lines){if($line -match '^([^\s]+)\s+(device|unauthorized|offline)(?:\s+(.*))?$'){$items+=@{id=$Matches[1];state=$Matches[2];details=([string]$Matches[3]).Trim()}}};$msg=if($items.Count-eq 0){'No device detected. Connect USB, enable USB debugging, and authorize this computer.'}else{''};return @{devices=@($items);message=$msg}}
function Recordings {$files=@(Get-ChildItem -LiteralPath $RecordDir -File -Filter '*.mp4' -ErrorAction SilentlyContinue|Sort-Object LastWriteTime -Descending|ForEach-Object {@{name=$_.Name;size=[long]$_.Length;modified=$_.LastWriteTime.ToString('o')}});$total=[long]0;foreach($f in $files){$total+=[long]$f.size};return @{files=@($files);totalSize=$total}}
function Body($r){if($r.ContentLength64-gt 8192){throw 'Request too large.'};$reader=New-Object IO.StreamReader($r.InputStream,$r.ContentEncoding);try{$t=$reader.ReadToEnd();if([string]::IsNullOrWhiteSpace($t)){return @{}};return ($t|ConvertFrom-Json)}finally{$reader.Dispose()}}
function LaunchScrcpy($mode){if(-not(Test-Path $Scrcpy)){throw 'scrcpy.exe is missing from core/scrcpy. Re-extract the complete ZIP.'};$s=Settings;$a=@("--max-size=$($s.maxSize)","--max-fps=$($s.maxFps)","--video-bit-rate=$($s.bitrate)",'--window-title=Scrcpy Toolkit');if($mode-eq'record'){$o=Join-Path $RecordDir ('Phone-'+(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss')+'.mp4');$a+=@('--record',('"'+$o+'"'))};if(-not$s.audio){$a+='--no-audio'};Start-Process -FilePath $Scrcpy -ArgumentList $a -WorkingDirectory (Split-Path $Scrcpy)|Out-Null}
try{$Listener.Start();while($Listener.IsListening){$c=$Listener.GetContext();try{$r=$c.Request;$p=$r.Url.AbsolutePath.TrimEnd('/');if($r.HttpMethod-eq'OPTIONS'){$c.Response.StatusCode=204;$c.Response.Headers['Access-Control-Allow-Origin']='*';$c.Response.Headers['Access-Control-Allow-Methods']='GET, POST, OPTIONS';$c.Response.Headers['Access-Control-Allow-Headers']='Content-Type';$c.Response.Close();continue}
if($r.HttpMethod-eq'GET'-and$p-eq'/api/status'){$d=Devices;Reply $c @{ok=$true;version='1.0.0';deviceCount=@($d.devices|Where-Object state -eq 'device').Count}}
elseif($r.HttpMethod-eq'GET'-and$p-eq'/api/devices'){Reply $c (Devices)}
elseif($r.HttpMethod-eq'GET'-and$p-eq'/api/recordings'){Reply $c (Recordings)}
elseif($r.HttpMethod-eq'GET'-and$p-eq'/api/settings'){Reply $c @{settings=(Settings)}}
elseif($r.HttpMethod-eq'POST'-and$p-eq'/api/settings'){$b=Body $r;if(@(720,1024,1280,1600,1920,0)-notcontains[int]$b.maxSize){throw 'Unsupported size.'};if(@(15,24,30,45,60)-notcontains[int]$b.maxFps){throw 'Unsupported FPS.'};if(@('2M','4M','8M','12M','16M')-notcontains[string]$b.bitrate){throw 'Unsupported bitrate.'};$s=@{maxSize=[int]$b.maxSize;maxFps=[int]$b.maxFps;bitrate=[string]$b.bitrate;audio=[bool]$b.audio};$s|ConvertTo-Json|Set-Content -Encoding UTF8 $ConfigFile;Reply $c @{ok=$true;settings=$s}}
elseif($r.HttpMethod-eq'POST'-and$p-eq'/api/action'){$b=Body $r;switch([string]$b.action){'mirror'{LaunchScrcpy 'mirror';Reply $c @{ok=$true;message='Mirror window launched.'}}'record'{LaunchScrcpy 'record';Reply $c @{ok=$true;message='Recording started. Close its scrcpy window to finish the MP4.'}}'stop'{$n=0;Get-CimInstance Win32_Process -Filter "Name='scrcpy.exe'" -ErrorAction SilentlyContinue|Where-Object{$_.ExecutablePath-and([IO.Path]::GetFullPath($_.ExecutablePath)-eq[IO.Path]::GetFullPath($Scrcpy))}|ForEach-Object{Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue;$n++};Reply $c @{ok=$true;message="Closed $n toolkit scrcpy process(es)."}}'check'{Reply $c (Devices)}default{Reply $c @{error='Unknown action.'} 400}}}
elseif($r.HttpMethod-eq'POST'-and$p-eq'/api/open-recordings'){Start-Process explorer.exe -ArgumentList @($RecordDir);Reply $c @{ok=$true}}
elseif($r.HttpMethod-eq'GET'-and$p-eq'/api/cleanup-preview'){$days=30;if($r.QueryString['days']-match '^\d+$'){$days=[int]$r.QueryString['days']};if(@(30,60,90,180)-notcontains$days){throw 'Choose 30, 60, 90, or 180 days.'};$cut=(Get-Date).AddDays(-$days);$f=@(Get-ChildItem -LiteralPath $RecordDir -File -Filter '*.mp4'|Where-Object{$_.LastWriteTime-lt$cut}|ForEach-Object{@{name=$_.Name;size=[long]$_.Length}});Reply $c @{files=@($f);days=$days}}
elseif($r.HttpMethod-eq'POST'-and$p-eq'/api/cleanup'){$b=Body $r;$days=[int]$b.days;if(@(30,60,90,180)-notcontains$days-or-not$b.confirm){throw 'Cleanup not confirmed or invalid age.'};$cut=(Get-Date).AddDays(-$days);$n=0;$freed=[long]0;Get-ChildItem -LiteralPath $RecordDir -File -Filter '*.mp4'|Where-Object{$_.LastWriteTime-lt$cut}|ForEach-Object{$freed+=$_.Length;Remove-Item -LiteralPath $_.FullName -Force;$n++};Reply $c @{ok=$true;deleted=$n;freed=$freed}}
else{Reply $c @{error='Endpoint not found.'} 404}}catch{try{Reply $c @{error=$_.Exception.Message} 400}catch{try{$c.Response.Close()}catch{}}}}}finally{$Listener.Stop();$Listener.Close()}